    return result

def safe_divide(a, b):
    try:
        return round(a / b, 2)
    except ZeroDivisionError:
        return 'cannot divide by zero'

def parse_ages(texts):
    result = {'ok': [], 'errors': []}
    for t in texts:
        try:
            result['ok'].append(int(t))
        except ValueError:
            result['errors'].append(t)
    return result

