def percent(part, total):
    if total <= 0:
        raise ValueError('total must be positive')
    return round(part / total * 100, 1)

def order_total(orders):
    total = 0
    skipped = 0
    for order in orders:
        try:
            total += order['qty'] * order['price']
        except (KeyError, TypeError):
            skipped += 1
    return total, skipped

