def best_student(names, scores):
    best_name, best_score = names[0], scores[0]
    for name, score in zip(names, scores):
        if score > best_score:
            best_name, best_score = name, score
    return best_name

def receipt(items, prices, qtys):
    lines = []
    for n, (item, price, qty) in enumerate(zip(items, prices, qtys), start=1):
        lines.append(f'{n}. {item} x{qty} = {price * qty:.2f}')
    return lines
